import re
import json
from typing import Dict, List


def parse_script(text: str):
    lines = text.splitlines()
    nodes: List[Dict] = []
    edges: List[Dict] = []

    current_id = None
    content: List[str] = []

    def flush():
        nonlocal current_id, content
        if current_id is None:
            return
        # filter non-empty lines
        content_lines = [l for l in content if l.strip() != ""]
        if not content_lines:
            # create empty node
            nodes.append({"id": current_id, "text": "", "speaker": "", "type": "line"})
            return
        first = content_lines[0].lstrip()
        if re.match(r'^\d+\.', first):
            # choice node
            nodes.append({"id": current_id, "text": "", "speaker": "", "type": "choice"})
            for line in content_lines:
                line = line.strip()
                m = re.match(r'^\d+\.\s*(.*)$', line)
                option_text = m.group(1) if m else line
                # split on last arrow
                if "->" in option_text:
                    opt_text, target = option_text.rsplit("->", 1)
                    opt_text = opt_text.strip()
                    target = target.strip()
                else:
                    opt_text = option_text.strip()
                    target = None
                if target:
                    edges.append({"from": current_id, "to": target, "text": opt_text})
        else:
            # line node
            line_text = " ".join([l.strip() for l in content_lines])
            if "->" in line_text:
                before, target = line_text.rsplit("->", 1)
                target = target.strip()
            else:
                before = line_text
                target = None
            if ":" in before:
                speaker, text = before.split(":", 1)
                speaker = speaker.strip()
                text = text.strip()
            else:
                speaker = ""
                text = before.strip()
            nodes.append({"id": current_id, "text": text, "speaker": speaker, "type": "line"})
            if target:
                edges.append({"from": current_id, "to": target, "text": ""})

    for raw in lines:
        line = raw.strip()
        if line.startswith("[") and line.endswith("]"):
            flush()
            current_id = line[1:-1].strip()
            content = []
        else:
            content.append(raw)
    flush()

    # add implicit nodes for missing targets (e.g., End)
    node_ids = {n["id"] for n in nodes}
    for e in edges:
        if e["to"] not in node_ids:
            nodes.append({"id": e["to"], "text": "", "speaker": "", "type": "line"})
            node_ids.add(e["to"])

    return {"nodes": nodes, "edges": edges}


def to_dot(graph: Dict) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;", "  node [shape=box];"]
    for node in graph["nodes"]:
        nid = node["id"]
        ntype = node.get("type", "")
        label = nid
        if ntype == "line":
            speaker = node.get("speaker", "")
            text = node.get("text", "")
            if speaker:
                label = f"{nid}\\n{speaker}: {text}"
            else:
                label = f"{nid}\\n{text}"
        else:
            label = f"{nid}\\n(choice)"
        shape = "diamond" if ntype == "choice" else "box"
        lines.append(f"  \"{nid}\" [label=\"{label}\", shape={shape}];")
    for edge in graph["edges"]:
        frm = edge["from"]
        to = edge["to"]
        text = edge.get("text", "")
        if text:
            lines.append(f"  \"{frm}\" -> \"{to}\" [label=\"{text}\"]; ")
        else:
            lines.append(f"  \"{frm}\" -> \"{to}\";")
    lines.append("}")
    return "\n".join(lines)


if __name__ == "__main__":
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()
    graph = parse_script(text)
    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2)
    dot = to_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot)
